import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod"; const server = new McpServer({ name: "my-server", version: "1.0.0",
}); // Определение инструмента
server.tool( "my_tool", { param1: z.string().describe("Описание параметра 1"), param2: z.number().optional().describe("Описание параметра 2"), }, async ({ param1, param2 }) => { // Логика инструмента const result = { message: `Обработано: ${param1}`, value: param2 ??

