async ({ param }) => { try { const result = await someAsyncOperation(param); return { content: [{ type: "text", text: JSON.stringify(result) }], }; } catch (error) { return { content: [ { type: "text", text: JSON.stringify({ error: error instanceof Error ? error.message : String(error), }), }, ], }; }
