export const dailyReport: ScheduledTask = { id: "daily-report", name: "Ежедневный отчет", cronExpression: "0 9 * * *", // Каждый день в 9:00 enabled: true, execute: async () => { const messages: ChatMessage[] = [ { role: "user", content: "Создай краткий отчет о вчерашних событиях", }, ]; const result = await executeChatWithMCP(messages); await sendTelegramMessage("USER_ID", result.message.content); },
};
``` ### Пример 2: Мониторинг ```typescript
export const monitoring: ScheduledTask = { id: "monitoring", name: "Мониторинг системы", cronExpression: "*/30 * * * *", // Каждые 30 минут enabled: true, execute: async () => { // Проверка состояния системы const status = await checkSystemStatus(); if (status.hasIssues) { await sendTelegramMessage("USER_ID", `⚠️ Проблемы: ${status.issues}`); } },
};
``` ### Пример 3: Агрегация данных ```typescript
export const dataAggregation: ScheduledTask = { id: "data-aggregation", name: "Агрегация данных", cronExpression: "0 0 * * *", // Каждый день в полночь enabled: true, execute: async () => { // Сбор данных const data = await collectData(); // Анализ через AI const messages: ChatMessage[] = [ { role: "user", content: `Проанализируй следующие данные: ${JSON.stringify(data)}`, }, ]; const result = await executeChatWithMCP(messages); // Сохранение результатов await saveResults(result.message.content); },
};
